import json

ENTITY_TYPES = "corporation, creative-work, group, location, person, product"

def make_prompt(text):
    return (
        "Extract all structured information (entities and relations) from the following text. Output a JSON object.\n\n"
        f"Text: {text}\n"
        f"Entity types: {ENTITY_TYPES}\n\n"
        'Output format: {"entities": [...], "relations": [...], "events": []}\n'
        "For relations, head is the subject entity and tail is the object entity."
    )

def make_response(entities):
    out = {"entities": entities, "relations": [], "events": []}
    return json.dumps(out, ensure_ascii=False)

data_dir = "/root/autodl-tmp/struct_self_consist_ie/data/wnut17"
with open(f"{data_dir}/dev.json") as f:
    lines = [json.loads(l) for l in f]

result = []
for item in lines:
    conv = {
        "conversations": [
            {"from": "human", "value": make_prompt(item["text"])},
            {"from": "gpt", "value": make_response(item["entities"])}
        ]
    }
    result.append(conv)

with open(f"{data_dir}/llmfactory_dev.json", "w") as f:
    json.dump(result, f, indent=2, ensure_ascii=False)

print(f"Generated {len(result)} dev examples")
PYEOF
